import { FC } from 'react';
import { Link, LinkProps } from 'react-router-dom';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import AngleRightIcon from 'assets/images/icons/angle-right.svg?react';

import styles from './DashboardLink.module.scss';

interface IDashboardLinkProps extends LinkProps {
	to: string;
	type?: 'horizontal' | 'vertical';
	icon?: React.ReactNode;
	title?: string;
}

export const DashboardLink: FC<IDashboardLinkProps> = ({
	className,
	to,
	children,
	type = 'horizontal',
	icon,
	title,
	...props
}) => {
	return (
		<Link {...props} to={to} className={cn(className, styles.link, styles[type])}>
			{type === 'horizontal' && (
				<Flex align="center" justify="space-between" gap={12}>
					{children}
					{!children && title && (
						<Flex align="center" gap={12}>
							{icon}
							<Typography.Text style={{ lineHeight: '36px' }}>{title}</Typography.Text>
						</Flex>
					)}
					<Typography.Text type="secondary">
						<AngleRightIcon />
					</Typography.Text>
				</Flex>
			)}

			{type === 'vertical' && (
				<>
					<span className={styles.icon}>{icon}</span>
					<span>{title}</span>
				</>
			)}
		</Link>
	);
};
